module measured;
import "std/hash_map.nex" as maps;
import "std/hash.nex" as hash;

fn main()->unit!{io}{
 var table:maps::Map<i64,i64>=maps::empty(hash::integer,hash::equal<i64>);
 var index:i64=0;
 while index<4096{table=maps::put(table,index,index*3);index=index+1;}
 var total:i64=0;index=0;
 while index<4096{total=total+unwrap(maps::get(table,index));index=index+1;}
 index=0;while index<4096{table=maps::remove(table,index);index=index+1;}
 assert(maps::size(table)==0);print(total);
}
